examples.template:
MonarchFlowLayout(spacing: 16) {
    MonarchCard {
        VStack(alignment: .leading, spacing: 4) {
            Text({{title}}).monarchTextStyle(.subheading)
            Text({{descriptions.0}}).monarchTextStyle(.caption)
        }
        Text({{content}}).monarchTextStyle(.body)
    } footer: {
        MonarchButton({{action.label}}, variant: {{action.variant|case}}, size: {{action.size|case}}) {}
    }
    .frame(width: 256)
    MonarchCard(elevation: .sm) {
        VStack(alignment: .leading, spacing: 4) {
            Text({{title}}).monarchTextStyle(.subheading)
            Text({{descriptions.1}}).monarchTextStyle(.caption)
        }
        Text({{content}}).monarchTextStyle(.body)
    } footer: {
        MonarchButton({{action.label}}, variant: {{action.variant|case}}, size: {{action.size|case}}) {}
    }
    .frame(width: 256)
